import { spawn } from 'node:child_process';
import { access } from 'node:fs/promises';
import process from 'node:process';

const SERVER = { name: 'vercel-x-time', version: '0.1.0' };

const TOOLS = [
  {
    name: 'vercel_doctor',
    description: 'Check the local Vercel bridge runtime, token presence, and optional project/org environment bindings without exposing secrets.',
    inputSchema: { type: 'object', properties: {} }
  },
  {
    name: 'vercel_project_list',
    description: 'List Vercel projects visible to the current runtime credential.',
    inputSchema: {
      type: 'object',
      properties: { scope: { type: 'string' } },
      additionalProperties: false
    }
  },
  {
    name: 'vercel_link',
    description: 'Link a local project directory to a Vercel project non-interactively.',
    inputSchema: {
      type: 'object',
      required: ['cwd', 'project'],
      properties: {
        cwd: { type: 'string' },
        project: { type: 'string' },
        scope: { type: 'string' }
      },
      additionalProperties: false
    }
  },
  {
    name: 'vercel_dry_run',
    description: 'Run Vercel deployment dry-run and return the JSON manifest without creating a deployment.',
    inputSchema: {
      type: 'object',
      required: ['cwd'],
      properties: {
        cwd: { type: 'string' },
        project: { type: 'string' },
        scope: { type: 'string' },
        production: { type: 'boolean', default: true }
      },
      additionalProperties: false
    }
  },
  {
    name: 'vercel_deploy',
    description: 'Deploy a local project directory to Vercel. Production deploy is explicit via production=true.',
    inputSchema: {
      type: 'object',
      required: ['cwd'],
      properties: {
        cwd: { type: 'string' },
        project: { type: 'string' },
        scope: { type: 'string' },
        production: { type: 'boolean', default: true },
        skipDomain: { type: 'boolean', default: false }
      },
      additionalProperties: false
    }
  },
  {
    name: 'vercel_domain_add',
    description: 'Add a custom domain to a Vercel project.',
    inputSchema: {
      type: 'object',
      required: ['domain', 'project'],
      properties: {
        domain: { type: 'string' },
        project: { type: 'string' },
        scope: { type: 'string' },
        force: { type: 'boolean', default: false }
      },
      additionalProperties: false
    }
  },
  {
    name: 'vercel_domain_inspect',
    description: 'Inspect a domain and its Vercel verification/configuration state.',
    inputSchema: {
      type: 'object',
      required: ['domain'],
      properties: { domain: { type: 'string' }, scope: { type: 'string' } },
      additionalProperties: false
    }
  },
  {
    name: 'vercel_http_readback',
    description: 'Read back an HTTPS endpoint directly and report status, final URL, content type, and a short body prefix.',
    inputSchema: {
      type: 'object',
      required: ['url'],
      properties: { url: { type: 'string' } },
      additionalProperties: false
    }
  }
];

function token() {
  const t = process.env.VERCEL_TOKEN;
  if (!t) throw new Error('VERCEL_TOKEN_MISSING');
  return t;
}

function safeEnv() {
  return {
    token_present: Boolean(process.env.VERCEL_TOKEN),
    project_id: process.env.VERCEL_PROJECT_ID || null,
    org_id: process.env.VERCEL_ORG_ID || null
  };
}

async function exists(p) {
  try { await access(p); return true; } catch { return false; }
}

function run(args, { cwd } = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn('npx', ['--yes', 'vercel@latest', ...args], {
      cwd: cwd || process.cwd(),
      env: process.env,
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: process.platform === 'win32'
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', d => { stdout += d.toString(); });
    child.stderr.on('data', d => { stderr += d.toString(); });
    child.on('error', reject);
    child.on('close', code => {
      const clean = s => s.replaceAll(process.env.VERCEL_TOKEN || '__NO_TOKEN__', '[REDACTED]');
      resolve({ code, stdout: clean(stdout).trim(), stderr: clean(stderr).trim() });
    });
  });
}

function withAuth(args, input = {}) {
  const out = [...args, '--token', token(), '--no-color'];
  if (input.scope) out.push('--scope', input.scope);
  if (input.project) out.push('--project', input.project);
  return out;
}

async function callTool(name, input = {}) {
  if (name === 'vercel_doctor') {
    const runtime = await run(['--version']);
    return { ok: runtime.code === 0, node: process.version, npx_vercel: runtime.stdout || runtime.stderr, env: safeEnv() };
  }
  if (name === 'vercel_project_list') {
    return await run(withAuth(['project', 'ls', '--json'], input));
  }
  if (name === 'vercel_link') {
    if (!(await exists(input.cwd))) throw new Error('CWD_NOT_FOUND');
    return await run(withAuth(['link', input.cwd, '--yes', '--project', input.project], input), { cwd: input.cwd });
  }
  if (name === 'vercel_dry_run') {
    if (!(await exists(input.cwd))) throw new Error('CWD_NOT_FOUND');
    const args = ['deploy', input.cwd, '--dry', '--format=json', '--yes'];
    if (input.production !== false) args.push('--prod');
    return await run(withAuth(args, input), { cwd: input.cwd });
  }
  if (name === 'vercel_deploy') {
    if (!(await exists(input.cwd))) throw new Error('CWD_NOT_FOUND');
    const args = ['deploy', input.cwd, '--yes'];
    if (input.production !== false) args.push('--prod');
    if (input.skipDomain) args.push('--skip-domain');
    return await run(withAuth(args, input), { cwd: input.cwd });
  }
  if (name === 'vercel_domain_add') {
    const args = ['domains', 'add', input.domain, input.project];
    if (input.force) args.push('--force');
    return await run(withAuth(args, input));
  }
  if (name === 'vercel_domain_inspect') {
    return await run(withAuth(['domains', 'inspect', input.domain], input));
  }
  if (name === 'vercel_http_readback') {
    const u = new URL(input.url);
    if (u.protocol !== 'https:') throw new Error('HTTPS_REQUIRED');
    const res = await fetch(u, { redirect: 'follow', signal: AbortSignal.timeout(20000) });
    const text = await res.text();
    return {
      ok: res.ok,
      status: res.status,
      final_url: res.url,
      content_type: res.headers.get('content-type'),
      body_prefix: text.slice(0, 2000)
    };
  }
  throw new Error('UNKNOWN_TOOL');
}

function send(obj) { process.stdout.write(JSON.stringify(obj) + '\n'); }
function result(id, value) { send({ jsonrpc: '2.0', id, result: value }); }
function error(id, err) { send({ jsonrpc: '2.0', id, error: { code: -32000, message: String(err?.message || err) } }); }

let buf = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => {
  buf += chunk;
  let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i).trim();
    buf = buf.slice(i + 1);
    if (line) handle(line);
  }
});

async function handle(line) {
  let msg;
  try { msg = JSON.parse(line); } catch { return; }
  const { id, method, params } = msg;
  try {
    if (method === 'initialize') {
      result(id, {
        protocolVersion: params?.protocolVersion || '2025-06-18',
        capabilities: { tools: {} },
        serverInfo: SERVER
      });
      return;
    }
    if (method === 'notifications/initialized') return;
    if (method === 'ping') { result(id, {}); return; }
    if (method === 'tools/list') { result(id, { tools: TOOLS }); return; }
    if (method === 'tools/call') {
      const value = await callTool(params?.name, params?.arguments || {});
      result(id, { content: [{ type: 'text', text: JSON.stringify(value, null, 2) }], isError: false });
      return;
    }
    if (id !== undefined) error(id, new Error('METHOD_NOT_FOUND'));
  } catch (e) {
    if (id !== undefined) {
      result(id, { content: [{ type: 'text', text: JSON.stringify({ ok: false, error: String(e?.message || e) }) }], isError: true });
    }
  }
}
